const F = [
  ['SH Display', '400', 'normal', ''],
  ['SH Label', '800', 'italic', ''],
  ['SH Label', '700', 'italic', ''],
  ['SH Label', '600', 'normal', ''],
  ['SH Poster', '400', 'normal', ''],
  ['SH Mono', '400', 'normal', ''],
];
export function loadFonts() {
  if (typeof FontFace === 'undefined' || !document.fonts) return Promise.resolve();
  return Promise.all(F.map(([family, weight, style, b64]) => {
    const bin = atob(b64), u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
    const f = new FontFace(family, u.buffer, { weight, style, display: 'swap' }); document.fonts.add(f); return f.load().catch(() => {});
  }));
}
